from pathlib import Path

app = Path("app.py")
text = app.read_text()
old = 'APP_VERSION = "25.5"'
new = 'APP_VERSION = "25.6"'
if old not in text:
    raise SystemExit("Expected APP_VERSION 25.5 not found")
app.write_text(text.replace(old, new, 1))

readme = Path("README.txt")
r = readme.read_text()
block = "v25.6 — REPO HYGIENE CLEANUP\n- Removed 24 one-off GitHub Actions workflows, 23 one-off patch scripts (scripts/), 2 one-off scripts and a trigger marker (tools/), and a stray build marker file — all were single-use automation for applying specific historical patches (v24.1 through v25.5) and had already served their purpose; the actual changes they made are already permanently baked into app.py. Keeping them around was pure accumulating clutter, and one workflow (apply-version-pill-source-of-truth.yml) ran on every single future push to main indefinitely with write access — safe in practice (defensively coded to no-op once already applied) but not something that should be a permanent fixture.\n- Added .gitignore (__pycache__/, *.pyc, .pytest_cache/, *.sqlite3, .env, editor/OS cruft) and untracked a compiled .pyc binary that had been accidentally committed — there was previously no .gitignore at all, which is exactly what let that happen.\n- No changes to app.py itself; compiles cleanly and all 14 existing tests still pass.\n- NOTE: this changelog has a real gap — v24.5 through v25.5 were never documented here despite shipping real changes (paid-feed Safari/chart fixes, top-setup scoring, mobile layout/stability passes, cache bounds, request coalescing, trade-plan integrity). Worth a dedicated follow-up pass to backfill those entries from the corresponding scripts' git history before this file's tracking gets even further behind actual shipped behavior.\n\n"
if not r.startswith("v25.6 — REPO HYGIENE CLEANUP"):
    readme.write_text(block + r)

Path(".gitignore").write_text("# Python\n__pycache__/\n*.py[cod]\n*.pyo\n.pytest_cache/\n\n# Local data\n*.sqlite3\n*.sqlite3-journal\nmarket_rotation_setups.sqlite3\n\n# Editor/OS cruft\n.DS_Store\n.vscode/\n.idea/\n\n# Env files (never commit real secrets)\n.env\n.env.local\n")

